# LVGL display driver for the Waveshare RP2350-Touch-LCD-4.
#
# `import display_driver` is all an application (e.g. code generated by
# lvgl-mpy-builder) needs: it starts LVGL on the rgbpanel framebuffer and
# runs lv.timer_handler() periodically, so the application has no main loop.
#
# LVGL renders straight into the framebuffer that the PIO/DMA scan-out reads
# (DIRECT mode, one buffer, no copy). The framebuffer is rgbpanel.WIDTH x
# rgbpanel.HEIGHT: 240x240 shown as 2x2 pixels when the board has no PSRAM.
#
# The GT911 touch controller is registered as LVGL pointer device (touch, indev).
#
# Importing again (or after a soft reset) is safe: the panel keeps running,
# LVGL and the timer are set up once per MicroPython session.
#
# display_driver.stop() stops the periodic timer_handler, for applications
# that want their own loop; display_driver.start() restarts it.

import lvgl as lv
import micropython
import rgbpanel
from machine import Timer

PERIOD_MS = 5

WIDTH = rgbpanel.WIDTH
HEIGHT = rgbpanel.HEIGHT

rgbpanel.init()
lv.init()
rgbpanel.lv_tick_install()

_fb = rgbpanel.framebuffer()

disp = lv.display_create(WIDTH, HEIGHT)
disp.set_color_format(lv.COLOR_FORMAT.RGB565)
disp.set_buffers(_fb, None, len(_fb) * 2, lv.DISPLAY_RENDER_MODE.DIRECT)


def _flush(d, area, px):
    # Already rendered into the scanned-out framebuffer.
    d.flush_ready()


disp.set_flush_cb(_flush)

# Touch (GT911 on I2C1). Coordinates are scaled to the framebuffer.
try:
    import gt911

    touch = gt911.GT911(scale=480 // WIDTH)
    indev = touch.lv_register()
except OSError as e:
    touch = indev = None
    print("display_driver: no touch:", e)

_timer = None
_busy = False


def _task(_):
    global _busy
    if _busy:
        return
    _busy = True
    try:
        lv.timer_handler()
    finally:
        _busy = False


def _tick(_):
    try:
        micropython.schedule(_task, None)
    except RuntimeError:
        pass  # schedule queue full: the next tick will catch up


def start():
    global _timer
    if _timer is None:
        _timer = Timer(period=PERIOD_MS, mode=Timer.PERIODIC, callback=_tick)


def stop():
    global _timer
    if _timer is not None:
        _timer.deinit()
        _timer = None


start()
